// static
bool InstallControllerStubDispatch::Accept(
    InstallController* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kInstallController_BeginUpdate_Name: {

      DCHECK(message->is_serialized());
      internal::InstallController_BeginUpdate_Params_Data* params =
          reinterpret_cast<internal::InstallController_BeginUpdate_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      std::string p_device_id{};
      ::base::FilePath p_filepath{};
      InstallController_BeginUpdate_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadDeviceId(&p_device_id))
        success = false;
      if (success && !input_data_view.ReadFilepath(&p_filepath))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            InstallController::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->BeginUpdate(
std::move(p_device_id), 
std::move(p_filepath));
      return true;
    }
    case internal::kInstallController_AddObserver_Name: {

      DCHECK(message->is_serialized());
      internal::InstallController_AddObserver_Params_Data* params =
          reinterpret_cast<internal::InstallController_AddObserver_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      ::mojo::PendingRemote<UpdateProgressObserver> p_observer{};
      InstallController_AddObserver_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_observer =
            input_data_view.TakeObserver<decltype(p_observer)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            InstallController::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->AddObserver(
std::move(p_observer));
      return true;
    }
  }
  return false;
}

// static
bool InstallControllerStubDispatch::AcceptWithResponder(
    InstallController* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kInstallController_BeginUpdate_Name: {
      break;
    }
    case internal::kInstallController_AddObserver_Name: {
      break;
    }
  }
  return false;
}


