// static
bool StructTraits<::ash::firmware_update::mojom::FirmwareUpdate::DataView, ::ash::firmware_update::mojom::FirmwareUpdatePtr>::Read(
    ::ash::firmware_update::mojom::FirmwareUpdate::DataView input,
    ::ash::firmware_update::mojom::FirmwareUpdatePtr* output) {
  bool success = true;
  ::ash::firmware_update::mojom::FirmwareUpdatePtr result(::ash::firmware_update::mojom::FirmwareUpdate::New());
  
      if (success && !input.ReadDeviceId(&result->device_id))
        success = false;
      if (success && !input.ReadDeviceName(&result->device_name))
        success = false;
      if (success && !input.ReadDeviceVersion(&result->device_version))
        success = false;
      if (success && !input.ReadDeviceDescription(&result->device_description))
        success = false;
      if (success && !input.ReadPriority(&result->priority))
        success = false;
      if (success && !input.ReadFilepath(&result->filepath))
        success = false;
      if (success && !input.ReadChecksum(&result->checksum))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ash::firmware_update::mojom::InstallationProgress::DataView, ::ash::firmware_update::mojom::InstallationProgressPtr>::Read(
    ::ash::firmware_update::mojom::InstallationProgress::DataView input,
    ::ash::firmware_update::mojom::InstallationProgressPtr* output) {
  bool success = true;
  ::ash::firmware_update::mojom::InstallationProgressPtr result(::ash::firmware_update::mojom::InstallationProgress::New());
  
      if (success)
        result->percentage = input.percentage();
      if (success && !input.ReadState(&result->state))
        success = false;
  *output = std::move(result);
  return success;
}

