void UpdateProviderAsyncWaiter::PrepareForUpdate(
    const std::string& device_id, ::mojo::PendingRemote<InstallController>* out_controller) {
  base::RunLoop loop;
  proxy_->PrepareForUpdate(std::move(device_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingRemote<InstallController>* out_controller
,
             ::mojo::PendingRemote<InstallController> controller) {*out_controller = std::move(controller);
            loop->Quit();
          },
          &loop,
          out_controller));
  loop.Run();
}

::mojo::PendingRemote<InstallController> UpdateProviderAsyncWaiter::PrepareForUpdate(
    const std::string& device_id) {
  ::mojo::PendingRemote<InstallController> async_wait_result;
  PrepareForUpdate(std::move(device_id),&async_wait_result);
  return async_wait_result;
}

void UpdateProviderAsyncWaiter::FetchInProgressUpdate(
    FirmwareUpdatePtr* out_update) {
  base::RunLoop loop;
  proxy_->FetchInProgressUpdate(
      base::BindOnce(
          [](base::RunLoop* loop,
             FirmwareUpdatePtr* out_update
,
             FirmwareUpdatePtr update) {*out_update = std::move(update);
            loop->Quit();
          },
          &loop,
          out_update));
  loop.Run();
}

FirmwareUpdatePtr UpdateProviderAsyncWaiter::FetchInProgressUpdate(
    ) {
  FirmwareUpdatePtr async_wait_result;
  FetchInProgressUpdate(&async_wait_result);
  return async_wait_result;
}




